// Extraer información del mensaje
const message = $input.item.json.message;
const chatId = message.chat.id;
const userId = message.from.id;
const username = message.from.username || 'sin_username';
const text = message.text || '';

// Parsear comando
const command = text.split(' ')[0].toLowerCase();
const args = text.split(' ').slice(1).join(' ');

return {
  json: {
    chatId: chatId,
    userId: userId.toString(),
    username: username,
    command: command,
    args: args,
    fullText: text
  }
};

return {
  json: {
    chatId: $json.chatId,
    message: '¡Hola! 👋

Soy tu asistente de entrenamiento.

Comandos disponibles:
/rutina - Ver rutina actual
/log <ejercicio> <sets>x<reps> @<peso> - Registrar ejercicio
/progreso <ejercicio> - Ver progreso
/help - Ayuda'
  }
};

return {
  json: {
    chatId: $json.chatId,
    message: '📋 Comandos disponibles:

/rutina - Ver tu rutina actual
/log squat 5x5 @100 - Registrar ejercicio
/progreso squat - Ver progreso de un ejercicio
/nueva - Crear rutina nueva

Ejemplo de log:
/log bench press 3x8 @80'
  }
};

// Formatear resultado de BigQuery a mensaje bonito
const data = $input.all();
const chatId = $('Command Router').item.json.chatId;

if (data.length === 0) {
  return {
    json: {
      chatId: chatId,
      message: '❌ No tenés una rutina activa.\n\nUsá /nueva para crear una.'
    }
  };
}

let message = '💪 Tu rutina actual:\n\n';
let currentDay = '';

for (const row of data) {
  if (row.json.dia !== currentDay) {
    currentDay = row.json.dia;
    message += `\n🔹 Día ${currentDay}\n`;
  }
  message += `• ${row.json.ejercicio}: ${row.json.prescripcion}\n`;
}

return {
  json: {
    chatId: chatId,
    message: message
  }
};

// Parsear comando /log
// Formato esperado: /log squat 5x5 @100
const args = $json.args;
const userId = $json.userId;
const chatId = $json.chatId;

// Regex para parsear: ejercicio sets×reps @peso
const regex = /^(.+?)\s+(\d+)x(\d+)\s*@([\d.]+)$/i;
const match = args.match(regex);

if (!match) {
  return {
    json: {
      chatId: chatId,
      error: true,
      message: '❌ Formato incorrecto.\n\nUsa: /log ejercicio sets×reps @peso\nEjemplo: /log squat 5x5 @100'
    }
  };
}

const [, ejercicio, sets, reps, peso] = match;

return {
  json: {
    chatId: chatId,
    userId: userId,
    ejercicio: ejercicio.trim(),
    sets: parseInt(sets),
    reps: parseInt(reps),
    peso: parseFloat(peso),
    error: false
  }
};

const chatId = $json.chatId;
const ejercicio = $json.ejercicio;
const sets = $json.sets;
const reps = $json.reps;
const peso = $json.peso;

return {
  json: {
    chatId: chatId,
    message: `✅ Registrado!\n\n${ejercicio}\n${sets}×${reps} @${peso}kg\n\n¡Buen trabajo! 💪`
  }
};
